package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.Closeable;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for MappingIterator#nextValue().
 * Since MappingIterator is a complex class with protected fields and logic tightly coupled 
 * to Jackson internals, this test uses a Mockito-based approach to simulate the internal state.
 */
public class MappingIterator_nextValue_TriageGen0Test {

    private MappingIterator<Object> _iterator;

    @Mock
    private JsonParser _parser;

    @Mock
    private JsonDeserializer<Object> _deserializer;

    @Mock
    private Object _context;

    // We use a subclass to expose protected fields for testing purposes 
    // as MappingIterator is difficult to instantiate with specific internal states directly.
    private static class TestMappingIterator extends MappingIterator<Object> {
        boolean _hasNextChecked = false;
        JsonParser _parser;
        JsonDeserializer<Object> _deserializer;
        Object _context;
        Object _updatedValue;
        boolean _hasNextValueResult = true;

        public TestMappingIterator(JsonParser parser, JsonDeserializer<Object> deserializer, Object context) {
            this._parser = parser;
            this._deserializer = deserializer;
            this._context = context;
        }

        @Override
        public boolean hasNextValue() throws IOException {
            return _hasNextValueResult;
        }

        // Override to bypass abstract requirement or use spy
        @Override
        protected Object _throwNoSuchElement() {
            throw new RuntimeException("NoSuchElementException");
        }
    }

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    public void testNextValue_NoHasNextChecked_And_NoHasNextValue() throws IOException {
        _iterator = new TestMappingIterator(_parser, _deserializer, _context);
        _iterator._hasNextChecked = false;
        _iterator._hasNextValueResult = false;

        try {
            _iterator.nextValue();
        } catch (RuntimeException e) {
            assertEquals("NoSuchElementException", e.getMessage());
        }
    }

    @Test
    public void testNextValue_NoHasNextChecked_But_HasNextValue_And_ParserIsNull() throws IOException {
        _iterator = new TestMappingIterator(null, _deserializer, _context);
        _iterator._hasNextChecked = false;
        _iterator._hasNextValueResult = true;

        try {
            _iterator.nextValue();
        } catch (RuntimeException e) {
            assertEquals("NoSuchElementException", e.getMessage());
        }
    }

    @Test
    public void testNextValue_Success_WithNewObject() throws IOException {
        Object expectedValue = new Object();
        _iterator = new TestMappingIterator(_parser, _deserializer, _context);
        _iterator._hasNextChecked = true; // bypass hasNextValue check
        _iterator._updatedValue = null;

        when(_deserializer.deserialize(eq(_parser), eq(_context))).thenReturn(expectedValue);

        Object result = _iterator.nextValue();

        assertEquals(expectedValue, result);
        verify(_parser).clearCurrentToken();
    }

    @Test
    public void testNextValue_Success_WithUpdatedObject() throws IOException {
        Object updatedValue = new Object();
        _iterator = new TestMappingIterator(_parser, _deserializer, _context);
        _iterator._hasNextChecked = true;
        _iterator._updatedValue = updatedValue;

        doNothing().when(_deserializer).deserialize(eq(_parser), eq(_context), eq(updatedValue));

        Object result = _iterator.nextValue();

        assertEquals(updatedValue, result);
        verify(_parser).clearCurrentToken();
    }

    @Test
    public void testNextValue_Success_After_HasNextCheckedFalse() throws IOException {
        Object expectedValue = new Object();
        _iterator = new TestMappingIterator(_parser, _deserializer, _context);
        _iterator._hasNextChecked = false;
        _iterator._hasNextValueResult = true;
        _iterator._updatedValue = null;

        when(_deserializer.deserialize(eq(_parser), eq(_context))).thenReturn(expectedValue);

        Object result = _iterator.nextValue();

        assertEquals(expectedValue, result);
        verify(_parser).clearCurrentToken();
    }

    @Test
    public void testNextValue_ThrowsIOException_StillClearsToken() throws IOException {
        _iterator = new TestMappingIterator(_parser, _deserializer, _context);
        _iterator._hasNextChecked = true;
        _iterator._updatedValue = null;

        when(_deserializer.deserialize(any(), any())).thenThrow(new IOException("Parse error"));

        try {
            _iterator.nextValue();
        } catch (IOException e) {
            assertEquals("Parse error", e.getMessage());
        }

        // Verify finally block executed
        verify(_parser).clearCurrentToken();
    }

    @Test
    public void testNextValue_ThrowsRuntimeException_StillClearsToken() throws IOException {
        _iterator = new TestMappingIterator(_parser, _deserializer, _context);
        _iterator._hasNextChecked = true;
        _iterator._updatedValue = null;

        when(_deserializer.deserialize(any(), any())).thenThrow(new RuntimeException("Fatal error"));

        try {
            _iterator.nextValue();
        } catch (RuntimeException e) {
            assertEquals("Fatal error", e.getMessage());
        }

        // Verify finally block executed
        verify(_parser).clearCurrentToken();
    }
}
